// These fixtures are independent backend YAML, not generated by the provider.
const awsBackendFixture = `version: "1.0"
aws_region_name: us-east-2
aws_access_key_id: " synthetic-id "
aws_secret_access_key: " synthetic-key\n"
use_role_arn: true
aws_role_arn: arn:aws:iam::123456789012:role/example
use_service_account: true
service_account: mapped-account
create_if_not_exists: true
enable_allowed_commands: true
allowed_commands: "s3:ls,ec2:describe-instances"
`
const keyspacesBackendFixture = `version: "2.0"
keyspace: application
keyspaces_endpoint: cassandra.us-east-2.amazonaws.com
aws_region_name: us-east-2
aws_access_key_id: " synthetic-id "
aws_secret_access_key: " synthetic-key\n"
use_role_arn: true
aws_role_arn: arn:aws:iam::123456789012:role/example
use_service_account: true
service_account: mapped-account
create_if_not_exists: true
`

func cloudFixture(t *testing.T, typ string) map[string]interface{} {
	t.Helper()
	fixture := awsBackendFixture
	if typ == "keyspaces" {
		fixture = keyspacesBackendFixture
	}
	var wire map[string]interface{}
	if err := yaml.UnmarshalStrict([]byte(fixture), &wire); err != nil {
		t.Fatal("invalid independent fixture")
	}
	return wire
}

func cloudWire(t *testing.T, d *schema.ResourceData, typ string) map[string]interface{} {
	t.Helper()
	cfg, err := schemaToResourceIntegrationConfiguration(d, typ)
	if err != nil {
		t.Fatal("cloud configuration was rejected:", err)
	}
	data, err := yaml.Marshal(cfg)
	if err != nil {
		t.Fatal("cloud encoding failed")
	}
	var wire map[string]interface{}
	if err := yaml.UnmarshalStrict(data, &wire); err != nil {
		t.Fatal("cloud decode failed")
	}
	delete(wire, "name") // Provider-only legacy metadata, ignored by backend.
	return wire
}

func TestAWSKeyspacesBackendContract(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		t.Run(typ, func(t *testing.T) {
			values := map[string]interface{}{
				"name": "cloud", "type": typ, "use_role_arn": true,
				"aws_role_arn":        "arn:aws:iam::123456789012:role/example",
				"use_service_account": true, "service_account": "mapped-account", "create_if_not_exists": true,
			}
			if typ == "aws" {
				values["region_name"], values["access_key_id"], values["secret_access_key"] = "us-east-2", " synthetic-id ", " synthetic-key\n"
				values["enable_allowed_commands"], values["allowed_commands"] = true, "s3:ls,ec2:describe-instances"
			} else {
				values["aws_region_name"], values["aws_access_key_id"], values["aws_secret_access_key"] = "us-east-2", " synthetic-id ", " synthetic-key\n"
				values["keyspace"], values["keyspaces_endpoint"], values["version"] = "application", "cassandra.us-east-2.amazonaws.com", "2.0"
			}
			d := schema.TestResourceDataRaw(t, ResourceAdaptiveResource().Schema, values)
			if !reflect.DeepEqual(cloudWire(t, d, typ), cloudFixture(t, typ)) {
				t.Error("outgoing YAML differs from independent backend fixture (values withheld)")
			}
		})
	}
}

func TestAWSKeyspacesReverseContract(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		t.Run(typ, func(t *testing.T) {
			d := schema.TestResourceDataRaw(t, ResourceAdaptiveResource().Schema, map[string]interface{}{"name": "cloud", "type": typ})
			fixture := cloudFixture(t, typ)
			if err := integrations.ApplyIntegrationConfig(d, typ, fixture); err != nil {
				t.Fatal("fixture refresh failed")
			}
			if !reflect.DeepEqual(cloudWire(t, d, typ), fixture) {
				t.Error("fixture reverse mapping lost backend fields (values withheld)")
			}
			for key, value := range fixture {
				if key == "version" && typ == "aws" {
					continue
				}
				attr, ok := integrations.AttrForConfigKey(typ, key)
				if !ok {
					t.Errorf("missing reverse mapping for %s", key)
					continue
				}
				before := d.Get(attr)
				for _, absent := range []map[string]interface{}{{"unrelated": true}, {key: nil}} {
					if err := integrations.ApplyIntegrationConfig(d, typ, absent); err != nil {
						t.Fatal(err)
					}
					if !reflect.DeepEqual(d.Get(attr), before) {
						t.Errorf("absent/null %s changed state", attr)
					}
				}
				var empty interface{} = ""
				if _, isBool := value.(bool); isBool {
					empty = false
				}
				if err := integrations.ApplyIntegrationConfig(d, typ, map[string]interface{}{key: empty}); err != nil {
					t.Fatal(err)
				}
				if d.Get(attr) != empty {
					t.Errorf("explicit zero %s did not clear", attr)
				}
			}
		})
	}
}

func TestAWSKeyspacesIAMCapabilities(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces", "mysql"} {
		for _, attr := range []string{"aws_role_arn", "use_rds_iam", "use_irsa", "aws_region", "aws_service_account", "aws_access_key_id", "aws_secret_access_key"} {
			t.Run(typ+"/"+attr, func(t *testing.T) {
				var value interface{} = "configured"
				if attr == "use_rds_iam" || attr == "use_irsa" {
					value = true
				}
				d := schema.TestResourceDataRaw(t, ResourceAdaptiveResource().Schema, map[string]interface{}{"name": "cloud", "type": typ, attr: value})
				_, err := schemaToResourceIntegrationConfiguration(d, typ)
				allowed := typ == "mysql" || (attr == "aws_role_arn") || (typ == "keyspaces" && (attr == "aws_access_key_id" || attr == "aws_secret_access_key"))
				if (err == nil) != allowed {
					t.Error("incorrect IAM capability boundary")
				}
			})
		}
	}
}

func TestAWSKeyspacesSensitiveSchema(t *testing.T) {
	s := ResourceAdaptiveResource().Schema
	for _, attr := range []string{"access_key_id", "secret_access_key", "aws_access_key_id", "aws_secret_access_key", "service_account"} {
		if !s[attr].Sensitive {
			t.Errorf("%s must remain sensitive", attr)
		}
	}
	for _, attr := range []string{"service_account", "aws_role_arn"} {
		if s[attr].Computed {
			t.Errorf("shared %s cannot become globally computed", attr)
		}
	}
}

// Exercise the SDK diff and its actual apply-time ResourceData, not only a
// stand-alone suppression callback. Omission retains observation; explicit
// false/empty clears must not suffer computed-string fallback.
func TestAWSKeyspacesSDKOwnership(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		for _, clear := range []bool{false, true} {
			t.Run(typ+map[bool]string{false: "/omit", true: "/clear"}[clear], func(t *testing.T) {
				r := ResourceAdaptiveResource()
				d := schema.TestResourceDataRaw(t, r.Schema, map[string]interface{}{"name": "cloud", "type": typ})
				d.SetId("r-1")
				fixture := cloudFixture(t, typ)
				delete(fixture, "aws_access_key_id")
				delete(fixture, "aws_secret_access_key")
				if err := integrations.ApplyIntegrationConfig(d, typ, fixture); err != nil {
					t.Fatal(err)
				}
				values := map[string]interface{}{"name": "cloud", "type": typ, "tags": []interface{}{"changed"}}
				for key, value := range fixture {
					attr, ok := integrations.AttrForConfigKey(typ, key)
					if !ok {
						continue
					}
					if clear {
						if _, isBool := value.(bool); isBool {
							values[attr] = false
						} else {
							values[attr] = ""
						}
					}
				}
				state := d.State()
				// Core supplies RawConfig on the state passed to SDK Diff.
				raw := map[string]cty.Value{}
				for attr, value := range values {
					switch v := value.(type) {
					case string:
						raw[attr] = cty.StringVal(v)
					case bool:
						raw[attr] = cty.BoolVal(v)
					case []interface{}:
						raw[attr] = cty.ListVal([]cty.Value{cty.StringVal("changed")})
					}
				}
				state.RawConfig = cty.ObjectVal(raw)
				diff, err := r.Diff(context.Background(), state, terraform.NewResourceConfigRaw(values), nil)
				if err != nil {
					t.Fatal(err)
				}
				planned, err := schema.InternalMap(r.Schema).Data(state, diff)
				if err != nil {
					t.Fatal(err)
				}
				wire := cloudWire(t, planned, typ)
				for key, value := range fixture {
					if key == "version" && typ == "aws" {
						continue
					}
					want := value
					if clear {
						if _, ok := value.(bool); ok {
							want = false
						} else {
							want = ""
						}
					}
					if !reflect.DeepEqual(wire[key], want) {
						t.Errorf("SDK ownership lost %s", key)
					}
				}
			})
		}
	}
}

func TestAWSKeyspacesDefaultsAndAuthModes(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		for _, mode := range []string{"omitted", "false", "role", "service-account", "both"} {
			t.Run(typ+"/"+mode, func(t *testing.T) {
				values := map[string]interface{}{"name": "cloud", "type": typ}
				if mode != "omitted" {
					values["use_role_arn"] = mode == "role" || mode == "both"
					values["use_service_account"] = mode == "service-account" || mode == "both"
				}
				d := schema.TestResourceDataRaw(t, ResourceAdaptiveResource().Schema, values)
				wire := cloudWire(t, d, typ)
				if wire["use_role_arn"] != (mode == "role" || mode == "both") || wire["use_service_account"] != (mode == "service-account" || mode == "both") {
					t.Fatal("auth modes changed")
				}
				if wire["aws_role_arn"] != "" || wire["service_account"] != "" || wire["create_if_not_exists"] != false {
					t.Fatal("omitted auth identifiers must remain empty")
				}
				if typ == "aws" && (wire["allowed_commands"] != "" || wire["enable_allowed_commands"] != false) {
					t.Fatal("omitted CLI policy must match backend defaults")
				}
			})
		}
	}
}

func TestAWSKeyspacesHeldSecretGuard(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		for _, key := range []string{"aws_access_key_id", "aws_secret_access_key", "service_account"} {
			for _, kind := range []string{"omitted", "null", "unknown", "supplied", "clear", "planned-disagreement"} {
				t.Run(typ+"/"+key+"/"+kind, func(t *testing.T) {
					attr, ok := integrations.AttrForConfigKey(typ, key)
					if !ok {
						t.Fatal("held-field mapping unavailable")
					}
					api := &fakeAPI{}
					client := api.start(t, func(w http.ResponseWriter, r *http.Request) {
						_ = json.NewEncoder(w).Encode(map[string]interface{}{"id": "r-1", "name": "cloud", "integrationType": typ, "redactedKeys": []string{key}, "redactedDigests": map[string]string{key: "opaque-baseline"}})
					})
					value := " synthetic-configured\n"
					values := map[string]interface{}{"name": "cloud", "type": typ, attr: value, "use_role_arn": true, "use_service_account": true}
					raw := map[string]cty.Value{}
					switch kind {
					case "null":
						raw[attr] = cty.NullVal(cty.String)
					case "unknown":
						raw[attr] = cty.UnknownVal(cty.String)
					case "supplied":
						raw[attr] = cty.StringVal(value)
					case "clear":
						raw[attr] = cty.StringVal("")
						values[attr] = ""
					case "planned-disagreement":
						raw[attr] = cty.StringVal(value)
						values[attr] = "opaque-marker"
					}
					d := secretUpdateData(t, values, raw)
					data, err := yaml.Marshal(cloudWire(t, d, typ))
					if err != nil {
						t.Fatal("serialization failed")
					}
					err = validateResourceSecretUpdate(context.Background(), d, client, data)
					allow := kind == "supplied" || kind == "clear"
					if (err == nil) != allow {
						t.Fatal("incorrect held-credential update decision")
					}
					if err != nil && (strings.Contains(err.Error(), value) || strings.Contains(err.Error(), "opaque-marker") || strings.Contains(err.Error(), "opaque-baseline")) {
						t.Fatal("credential diagnostic disclosed a value")
					}
				})
			}
		}
	}
}

// ignore_changes is Core-owned; model the retained known SDK plan to ensure
// serialization never replaces it with an explicit raw-config clear.
func TestAWSKeyspacesIgnoredClearRetainsKnownPlan(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		r := ResourceAdaptiveResource()
		d := schema.TestResourceDataRaw(t, r.Schema, map[string]interface{}{"name": "cloud", "type": typ})
		d.SetId("r-1")
		fixture := cloudFixture(t, typ)
		delete(fixture, "aws_access_key_id")
		delete(fixture, "aws_secret_access_key")
		if err := integrations.ApplyIntegrationConfig(d, typ, fixture); err != nil {
			t.Fatal(err)
		}
		raw := map[string]cty.Value{"name": cty.StringVal("cloud"), "type": cty.StringVal(typ)}
		plan := map[string]cty.Value{}
		for key, value := range fixture {
			attr, ok := integrations.AttrForConfigKey(typ, key)
			if !ok {
				continue
			}
			if v, ok := value.(bool); ok {
				raw[attr] = cty.False
				plan[attr] = cty.BoolVal(v)
			} else {
				raw[attr] = cty.StringVal("")
				plan[attr] = cty.StringVal(value.(string))
			}
		}
		planned, err := schema.InternalMap(r.Schema).Data(d.State(), &terraform.InstanceDiff{Attributes: map[string]*terraform.ResourceAttrDiff{}, RawConfig: cty.ObjectVal(raw), RawPlan: cty.ObjectVal(plan)})
		if err != nil {
			t.Fatal(err)
		}
		wire := cloudWire(t, planned, typ)
		for key, value := range fixture {
			if wire[key] != value {
				t.Errorf("raw clear overrode retained plan for %s", key)
			}
		}
	}
}

func TestAWSKeyspacesRejectUnsupportedNewControls(t *testing.T) {
	for _, tc := range []struct {
		typ, attr string
		value     interface{}
	}{
		{"mysql", "use_role_arn", true}, {"keyspaces", "enable_allowed_commands", true},
		{"keyspaces", "allowed_commands", "s3:ls"}, {"aws", "keyspace", "application"}, {"aws", "keyspaces_endpoint", "cassandra.example.test"},
	} {
		d := schema.TestResourceDataRaw(t, ResourceAdaptiveResource().Schema, map[string]interface{}{"name": "cloud", "type": tc.typ, tc.attr: tc.value})
		if _, err := schemaToResourceIntegrationConfiguration(d, tc.typ); err == nil {
			t.Errorf("unsupported %s/%s accepted", tc.typ, tc.attr)
		}
		if _, err := ResourceAdaptiveResource().Diff(context.Background(), nil, terraform.NewResourceConfigRaw(map[string]interface{}{"name": "cloud", "type": tc.typ, tc.attr: tc.value}), nil); err == nil {
			t.Errorf("unsupported %s/%s accepted during plan", tc.typ, tc.attr)
		}
	}
}

func TestAWSKeyspacesAppliedBaselineMapping(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		for _, key := range []string{"aws_access_key_id", "aws_secret_access_key", "service_account"} {
			for _, supplied := range []bool{false, true} {
				t.Run(typ+"/"+key+map[bool]string{false: "/omitted", true: "/supplied"}[supplied], func(t *testing.T) {
					attr, ok := integrations.AttrForConfigKey(typ, key)
					if !ok {
						t.Fatal("baseline mapping unavailable")
					}
					api := &fakeAPI{}
					client := api.start(t, func(w http.ResponseWriter, r *http.Request) {
						_ = json.NewEncoder(w).Encode(map[string]interface{}{"id": "r-1", "name": "cloud", "integrationType": typ})
					})
					values := map[string]interface{}{"name": "cloud", "type": typ, "applied_digests": map[string]interface{}{key: "opaque-baseline"}}
					raw := map[string]cty.Value{}
					if supplied {
						values[attr] = " synthetic-resupply\n"
						raw[attr] = cty.StringVal(" synthetic-resupply\n")
					}
					d := secretUpdateData(t, values, raw)
					data, err := yaml.Marshal(cloudWire(t, d, typ))
					if err != nil {
						t.Fatal("serialization failed")
					}
					err = validateResourceSecretUpdate(context.Background(), d, client, data)
					if (err == nil) != supplied {
						t.Fatal("last-write baseline did not retain credential mapping on old-server response")
					}
				})
			}
		}
	}
}

func TestAWSKeyspacesPolicyClearAloneConverges(t *testing.T) {
	r := ResourceAdaptiveResource()
	d := schema.TestResourceDataRaw(t, r.Schema, map[string]interface{}{"name": "cloud", "type": "aws", "enable_allowed_commands": true, "allowed_commands": "s3:ls"})
	d.SetId("r-1")
	values := map[string]interface{}{"name": "cloud", "type": "aws", "enable_allowed_commands": true, "allowed_commands": ""}
	state := d.State()
	state.RawConfig = cty.ObjectVal(map[string]cty.Value{"name": cty.StringVal("cloud"), "type": cty.StringVal("aws"), "enable_allowed_commands": cty.True, "allowed_commands": cty.StringVal("")})
	diff, err := r.Diff(context.Background(), state, terraform.NewResourceConfigRaw(values), nil)
	if err != nil {
		t.Fatal(err)
	}
	if change := diff.Attributes["allowed_commands"]; change == nil || change.NewComputed || change.New != "" {
		t.Fatal("clear alone did not plan a known empty allowlist")
	}
	planned, err := schema.InternalMap(r.Schema).Data(state, diff)
	if err != nil {
		t.Fatal(err)
	}
	wire := cloudWire(t, planned, "aws")
	if wire["allowed_commands"] != "" || wire["enable_allowed_commands"] != true {
		t.Fatal("clear did not preserve gate and emit backend allow-all empty string")
	}
	if err := integrations.ApplyIntegrationConfig(planned, "aws", map[string]interface{}{"allowed_commands": "", "enable_allowed_commands": true}); err != nil {
		t.Fatal(err)
	}
	// Read materializes unrelated computed credential metadata.
	if err := planned.Set("known_empty_secret_keys", []string{}); err != nil {
		t.Fatal(err)
	}
	if err := planned.Set("applied_digests", map[string]interface{}{}); err != nil {
		t.Fatal(err)
	}
	acknowledged := planned.State()
	acknowledged.RawConfig = state.RawConfig
	followup, err := r.Diff(context.Background(), acknowledged, terraform.NewResourceConfigRaw(values), nil)
	if err != nil {
		t.Fatal(err)
	}
	if followup != nil && !followup.Empty() {
		t.Fatal("acknowledged clear did not converge")
	}
}

func TestAWSKeyspacesMissingRawOwnershipRejected(t *testing.T) {
	for _, typ := range []string{"aws", "keyspaces"} {
		r := ResourceAdaptiveResource()
		d := schema.TestResourceDataRaw(t, r.Schema, map[string]interface{}{"name": "cloud", "type": typ, "use_role_arn": true, "aws_role_arn": "role"})
		d.SetId("r-1")
		if _, err := schemaToResourceIntegrationConfiguration(d, typ); err == nil {
			t.Errorf("%s update accepted unavailable raw ownership", typ)
		}
		if _, err := r.Diff(context.Background(), d.State(), terraform.NewResourceConfigRaw(map[string]interface{}{"name": "cloud", "type": typ, "tags": []interface{}{"changed"}}), nil); err == nil {
			t.Errorf("%s plan accepted unavailable raw ownership", typ)
		}
	}
}

func TestAWSKeyspacesSharedAttributesKeepOtherModes(t *testing.T) {
	for _, typ := range []string{"1password", "gcp"} {
		r := ResourceAdaptiveResource()
		values := map[string]interface{}{"name": "other", "type": typ, "aws_role_arn": "role", "service_account": "account", "use_service_account": true}
		d := schema.TestResourceDataRaw(t, r.Schema, values)
		d.SetId("r-1")
		diff, err := r.Diff(context.Background(), d.State(), terraform.NewResourceConfigRaw(map[string]interface{}{"name": "other", "type": typ}), nil)
		if err != nil {
			t.Fatal(err)
		}
		for _, attr := range []string{"aws_role_arn", "service_account", "use_service_account"} {
			if _, ok := diff.Attributes[attr]; !ok {
				t.Errorf("cloud ownership unexpectedly applied to %s/%s", typ, attr)
			}
		}
	}
}
